def derive_nodes(elf,binary):
 def asm(lo,hi):
  s=subprocess.check_output(['objdump','-d','-C','--no-show-raw-insn',f'--start-address={lo}',f'--stop-address={hi}',str(binary)],text=True)
  return [(int(m[1],16),m[2],m[3]) for l in s.splitlines() if (m:=re.match(r'\s*([a-f0-9]+):\s+(\w+)\s*(.*)',l))]
 def cstr(a):return elf.read(a,200).split(b'\0')[0].decode()
 binds={};name=None
 for a,op,arg in asm(0x26c2a60,0x26c325f):
  if op=='lea' and ',%rdi' in arg and '# ' in arg:name=cstr(int(arg.split('# ')[1].split()[0],16))
  if 'NT_' in arg:
   sym=re.search(r'BehaviorTree::(NT_\w+)',arg)[1];binds[sym]={'name':name,'hash':~zlib.crc32(name.encode())&0xffffffff}
 ins=asm(0x26e9ff0,0x26eaf63);d={a:(op,arg) for a,op,arg in ins};nxt={a:ins[i+1][0] for i,(a,_,_) in enumerate(ins[:-1])}
 for sym,row in binds.items():
  pc=0x26e9ff0;cur=None;eq=False;calls=[];seen=set()
  while True:
   assert pc not in seen,(sym,hex(pc));seen.add(pc)
   op,arg=d[pc]
   if 'NT_' in arg:cur=re.search(r'BehaviorTree::(NT_\w+)',arg)[1]
   if op=='cmp' and '%ebp' in arg:eq=cur==sym
   if op=='call':calls.append(arg.split(' <',1)[1][:-1])
   if op=='ret':break
   if op=='jmp' or op=='je' and eq or op=='jne' and not eq:pc=int(arg.split()[0],16)
   else:
    assert not(op.startswith('j') and op not in ('je','jne')),(op,arg)
    pc=nxt[pc]
  row['calls']=calls
 return binds

def derive_current_readers(binary):
 ins=[]
 for l in subprocess.check_output(['objdump','-d','-C','--no-show-raw-insn','--start-address=0x26eb070','--stop-address=0x26ec638',str(binary)],text=True).splitlines():
  m=re.match(r'\s*([a-f0-9]+):\s+(\w+)\s*(.*)',l)
  if m:ins.append((int(m[1],16),m[2],m[3]))
 d={a:(op,arg) for a,op,arg in ins};nxt={a:ins[i+1][0] for i,(a,_,_) in enumerate(ins[:-1])}
 result={}
 for sym,row in NODE_CONTRACTS.items():
  pc=0x26eb070;cur=None;eq=False;gt=False;calls=[];seen=set()
  while True:
   assert pc not in seen;seen.add(pc);op,arg=d[pc]
   if 'NT_' in arg:cur=re.search(r'BehaviorTree::(NT_\w+)',arg)[1]
