class Value:
 def __init__(self,name,fields,tuple_value=False):self.name,self.fields,self.tuple_value=name,fields,tuple_value
 def debug(self):
  if self.tuple_value:return self.name+'('+debug(self.fields)+')'
  return self.name+' { '+', '.join(k+': '+debug(v) for k,v in self.fields)+' }'
def debug(v):
 if isinstance(v,Value):return v.debug()
 if isinstance(v,list):return '['+', '.join(map(debug,v))+']'
 if v is None:return 'None'
 return str(v)
class Reader:
 def __init__(self,data):self.data=data;self.pos=0;self.items=0;self.cuts={0};self.versions=[];self.counts=[];self.node_counts={}
 def scalar(self,kind):
  n={'u8':1,'i16':2,'u32':4,'i32':4}[kind];self.cuts.add(self.pos)
  b=self.data[self.pos:self.pos+n]
  if len(b)!=n:raise ValueError('truncated')
  self.pos+=n
  return int.from_bytes(b,'little',signed=kind[0]=='i')
 def version(self,n):
  self.versions.append(self.pos)
  if self.scalar('u32')!=n:raise ValueError('version')
 def sequence(self,kind,count=None):
  if count is None:self.counts.append(self.pos);count=self.scalar('u32')
  if count>len(self.data):raise ValueError('hostile count')
  self.items+=count
  return [self.read(kind) for _ in range(count)]
 def read(self,kind):
  if kind in ('u8','i16','u32','i32'):return self.scalar(kind)
  if kind.startswith('Vec<'):return self.sequence(kind[4:-1])
  if kind=='BoolByte':return Value(kind,self.scalar('u8'),True)
  if kind=='SavedString':return Value(kind,self.sequence('u8'),True)
  if kind.startswith('Presence<'):
   present=self.read('BoolByte');v=self.read(kind[9:-1]) if present.fields else None
   return Value('Presence',[('present',present),('value',Value('Some',v,True) if v is not None else None)])
  if kind.startswith('BlackboardVector<'):
   self.version(1)
   return Value('BlackboardVector',[('data',self.sequence('BlackboardData<'+kind[17:-1]+'>')),('first_unused_index',self.read('i32'))])
  if kind.startswith('BlackboardData<'):
   self.version(1)
   return Value('BlackboardData',[('value',self.read(kind[15:-1])),('next_unused_index',self.read('i32'))])
  if kind=='DataEntry':
   self.version(1);label=self.read('u32');self.version(12)
   return Value(kind,[('label_hash',label),('indices',self.sequence('i32',12))])
  if kind=='NodeDefinition':
   self.version(3);shape=self.read('i32');h=self.read('u32');self.version(33)
   row=next((r for r in NODE_CONTRACTS.values() if r['hash']==h),None)
   if row is None:raise ValueError('unsupported unframed node hash')
   self.node_counts[row['name']]=self.node_counts.get(row['name'],0)+1
   fields=[]
   for k in row['fields']:
    ty={'shared':'SharedData','byte':'BoolByte','plot':'PlotCoord'}.get(k,'u32')
    fields.append(Value({'shared':'Shared','byte':'Byte','plot':'Plot'}.get(k,'Word'),self.read(ty),True))
   return Value(kind,[('shape',shape),('node_hash',h),('fields',fields),('num_shared_data',self.read('u32'))])
  if kind=='RecycledBehaviorTrees':
   self.version(0x10001);self.version(16);cap=self.read('u32');entries=self.sequence('BehaviorTreeEntry');bits=self.read('u32');self.counts.append(self.pos);count=self.read('u32');first=self.read('u32');last=self.read('u32')
   return Value(kind,[('capacity',cap),('entries',entries),('current_id_bits',bits),('first_free',first),('last_free',last),('free_indices',self.sequence('u32',count))])
  ver,fields=RECORDS[kind]
  if ver:self.version(ver)
  return Value(kind,[(name,self.read(ty)) for name,ty in fields])

HARNESS=r'''use c6_core::{player_ai_behavior_tree::{BehaviorTreeManager as Manager,Error},unit::Limits};
use std::io::Write;
fn u32at(b:&[u8],p:&mut usize)->usize{let n=u32::from_le_bytes(b[*p..*p+4].try_into().unwrap())as usize;*p+=4;n}
fn main(){let args:Vec<_>=std::env::args().collect();let input=std::fs::read(&args[1]).unwrap();let mut output=std::io::BufWriter::new(std::fs::File::create(&args[2]).unwrap());let mut p=0;let mut count=0;
while p<input.len(){let n=u32at(&input,&mut p);let items=u32at(&input,&mut p);let nc=u32at(&input,&mut p);let cuts:Vec<_>=(0..nc).map(|_|u32at(&input,&mut p)).collect();let nv=u32at(&input,&mut p);let versions:Vec<_>=(0..nv).map(|_|u32at(&input,&mut p)).collect();let nn=u32at(&input,&mut p);let counts:Vec<_>=(0..nn).map(|_|u32at(&input,&mut p)).collect();let raw=&input[p..p+n];p+=n;
let exact=Limits{max_bytes:n,max_items:items};let(v,used,charged)=Manager::decode_prefix_with_items(raw,exact).unwrap();assert_eq!((used,charged),(n,items));assert_eq!(v.encode_with_items(exact).unwrap(),(raw.to_vec(),items));writeln!(output,"{v:?}").unwrap();
for cut in cuts{assert!(cut<n);assert!(Manager::decode(&raw[..cut],exact).is_err(),"record {count} cut {cut}");}
for limits in [Limits{max_bytes:n-1,..exact},Limits{max_items:items-1,..exact}]{assert_eq!(Manager::decode(raw,limits),Err(Error::ResourceLimit));assert_eq!(v.encode(limits),Err(Error::ResourceLimit));}
let mut trailing=raw.to_vec();trailing.push(77);assert_eq!(Manager::decode(&trailing,exact),Err(Error::Trailing));assert_eq!(Manager::decode_prefix_with_items(&trailing,exact).unwrap(),(v,n,items));
for offset in versions{let mut bad=raw.to_vec();bad[offset..offset+4].copy_from_slice(&0xdeadbeefu32.to_le_bytes());assert!(Manager::decode(&bad,exact).is_err());}
for offset in counts{let mut bad=raw.to_vec();bad[offset..offset+4].copy_from_slice(&u32::MAX.to_le_bytes());assert!(Manager::decode(&bad,exact).is_err());}
count+=1;}output.flush().unwrap();println!("{count}");}'''

def candidate(pin,wire,projection):
 pin=subprocess.check_output(['git','rev-parse',pin+'^{commit}'],cwd=ROOT,text=True).strip()
 archive=subprocess.check_output(['git','archive',pin],cwd=ROOT)
 with tempfile.TemporaryDirectory(prefix='c6-behavior-tree-') as tmp:
  tmp=Path(tmp);source=tmp/'source';source.mkdir();subprocess.run(['tar','-x','-C',str(source)],input=archive,check=True)
  driver=source/'tools/linux/player_ai_behavior_tree_audit.py'
  if driver.read_bytes()!=Path(__file__).read_bytes():raise ValueError('audit driver differs from committed candidate')
  sources={str(p.relative_to(source)):sha(p.read_bytes()) for p in sorted(source.rglob('*.rs')) if 'target' not in p.parts}
  module=source/'crates/c6-core/src/player_ai_behavior_tree.rs'
  if not module.exists():raise ValueError('missing committed module')
  lib=(source/'crates/c6-core/src/lib.rs').read_text()
  if 'pub mod player_ai_behavior_tree;' not in lib:raise ValueError('missing actual committed public module export')
  subprocess.run(['cargo','test','--offline','-p','c6-core','player_ai_behavior_tree'],cwd=source,check=True)
  subprocess.run(['cargo','clippy','--offline','-p','c6-core','--all-targets','--','-D','warnings'],cwd=source,check=True)
  subprocess.run(['cargo','build','--offline','--release','-p','c6-core'],cwd=source,check=True)
  (tmp/'driver.rs').write_text(HARNESS);(tmp/'records.bin').write_bytes(wire)
  subprocess.run(['rustc','--edition=2021','-Dwarnings','-O',str(tmp/'driver.rs'),'--extern','c6_core='+str(source/'target/release/libc6_core.rlib'),'-L','dependency='+str(source/'target/release/deps'),'-o',str(tmp/'candidate')],check=True)
  count=subprocess.check_output([str(tmp/'candidate'),str(tmp/'records.bin'),str(tmp/'projection')],text=True).strip()
  actual=(tmp/'projection').read_bytes()
  if actual!=projection:
   for i,(a,b) in enumerate(zip(actual,projection)):
    if a!=b:raise ValueError(f'full typed projection mismatch at {i}: {actual[max(0,i-50):i+100]!r} != {projection[max(0,i-50):i+100]!r}')
   raise ValueError('projection length mismatch')
  after={str(p.relative_to(source)):sha(p.read_bytes()) for p in sorted(source.rglob('*.rs')) if 'target' not in p.parts}
  if sources!=after:raise ValueError('candidate source changed during validation')
  return dict(commit=pin,archive_sha256=sha(archive),module_sha256=sha(module.read_bytes()),driver_sha256=sha(driver.read_bytes()),harness_sha256=sha(HARNESS.encode()),executable_sha256=sha((tmp/'candidate').read_bytes()),all_rust_sources_before=sources,all_rust_sources_after=after,records=int(count),full_typed_projection_sha256=sha(actual),projection_bytes=len(actual),unit_tests=4,strict_clippy=True,actual_public_export=True,source_injection=False)

